'use strict';
const Connections=(()=>{
  let data=null,admin=null,generation=0;
  const owner=()=>!demo&&model.user?.role==='owner';
  const labels={facebook:'Facebook',instagram:'Instagram',twilio:'Business calls',website:'Website'};
  function render(){return heading('Bring your customer channels together.','Connect the places customers contact you. Their enquiries arrive automatically.')+'<div id="connectionsData">'+(demo?'<section class="card"><p>This demo is read only. Connect channels from your own business workspace.</p></section>':'<p class="muted">Loading connections…</p>')+'</div>';}
  function action(name,label,id='',disabled=false){return '<button type="button" data-connection-action="'+name+'" data-id="'+esc(id)+'"'+(disabled?' disabled':'')+'>'+label+'</button>';}
  function formStart(id,title,intro){return '<section class="card"><h2>'+title+'</h2><p class="small">'+intro+'</p><form id="'+id+'"><div class="error" role="alert" hidden></div>';}
  function formEnd(label){return '<button class="primary" type="submit">'+label+'</button></form></section>';}
  function draw(){if(!data||currentView!=='integrations'||demo||!$('connectionsData'))return;
    const enabled=data.connections.filter(c=>c.status!=='disconnected'),noticeCode=new URLSearchParams(location.search).get('channel');
    const noticeText=noticeCode==='connected'?'Meta authorization completed. Choose an account below to finish connecting.':noticeCode==='no_accounts'?'No eligible account was shared. Grant access to a managed Facebook Page, or an Instagram professional account linked to a Page.':noticeCode==='failed'?'Meta authorization did not complete. Check the app permissions and try Connect again.':'';
    let html=(noticeText?'<div class="banner">'+noticeText+'</div>':'')+'<div class="section-note">'+(owner()?'Only business owners can connect and disconnect channels.':'Ask a business owner to connect or disconnect channels.')+' Enquiries retain the original source and customer interaction. Website visits are anonymous until a customer provides contact details.</div>';
    if(owner())html+='<div class="grid"><section class="card"><h2>Instagram & Facebook</h2><p class="small">Connect a Facebook Page inbox or an Instagram professional account linked to a Facebook Page.</p><div class="actions">'+action('meta','Connect Instagram','instagram',!data.metaReady)+action('meta','Connect Facebook','facebook',!data.metaReady)+'</div>'+(!data.metaReady?'<p class="small channel-note">The platform administrator needs to configure the platform’s Meta app before social accounts can connect.</p>':'<p class="small channel-note">Authorize your own account, then select which Page or Instagram account to collect from.</p>')+'</section>'+formStart('websiteConnection','Website enquiries','Create a customer enquiry form for your website and optionally count anonymous visits.')+field('label','Connection name','','text','maxlength="150"')+field('websiteOrigin','Website origin','','url','required placeholder="https://yourbusiness.com" maxlength="500"')+'<label class="checkbox"><input type="checkbox" name="visitsEnabled"> Count anonymous website visits</label>'+formEnd('Connect website')+'</div>';
    if(owner()&&data.assets.length)html+='<section class="card"><h2>Choose an authorized account</h2>'+data.assets.map(a=>'<div class="stat-line"><span><strong>'+esc(a.label)+'</strong><br><span class="small">'+labels[a.provider]+' · '+esc(a.externalId)+'</span></span>'+action('asset','Collect enquiries',a.id)+'</div>').join('')+'</section>';
    html+='<section class="card"><h2>Your connections</h2>'+(enabled.length?enabled.map(c=>'<article class="connection-card"><div class="card-head"><div><strong>'+esc(c.label)+'</strong><span class="row-sub">'+labels[c.provider]+' · '+esc(c.phone||c.websiteOrigin||c.externalId)+'</span></div>'+pill(c.status,c.status==='connected'?'accepted':'partial')+'</div><p class="small">'+(c.lastEventAt?'Last interaction: '+when(c.lastEventAt):'Waiting for the first customer interaction.')+'</p>'+(c.error?'<p class="error">'+esc(c.error)+'</p>':'')+(c.provider==='website'&&owner()&&c.status==='connected'?websiteCode(c):'')+(c.provider==='twilio'?'<p class="small">Call details arrive after calls end. Caller number, call status and duration are captured when provided by Twilio.</p>':'')+(owner()?'<div class="actions">'+action('disconnect','Disconnect',c.id)+'</div>':'')+'</article>').join(''):empty('No channels connected yet.','Connect a customer channel to start collecting enquiries.'))+'</section>';
    if(owner())html+=formStart('twilioConnection','Business phone calls · Twilio','Connect an existing Twilio business number. Your Account SID, Auth Token and Phone Number SID are available in the Twilio console.')+field('label','Connection name','','text','maxlength="150"')+'<div class="pair">'+field('accountSid','Account SID','','text','required minlength="34" maxlength="34" placeholder="AC…" autocomplete="off"')+field('numberSid','Phone Number SID','','text','required minlength="34" maxlength="34" placeholder="PN…" autocomplete="off"')+'</div>'+field('authToken','Auth Token','','password','required minlength="32" maxlength="32" autocomplete="off"')+'<p class="small">We verify that you manage this number and configure its call-completion callback. Call details appear in Enquiries; audio is not recorded by ProfitPlus.</p>'+formEnd('Connect business calls');
    if(data.pendingCount)html+='<section class="card"><h2>Waiting to be processed · '+data.pendingCount+'</h2><p class="small">These interactions have been safely collected. Resolve the stated issue, then retry. Up to 20 are shown.</p>'+data.pending.map(p=>'<div class="connection-card"><strong>'+esc(p.name||p.phone||p.email||p.label)+'</strong><span class="row-sub">'+labels[p.provider]+' · '+when(p.createdAt)+'</span><p class="lead-message">'+esc(p.message)+'</p><p class="small">'+esc(p.error||'Waiting for processing.')+'</p>'+(owner()?'<label>Customer matching<select data-pending-customer="'+esc(p.id)+'"><option value="">Match automatically</option>'+active('customers').map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('')+'</select></label>'+action('retry','Retry captured interaction',p.id):'')+'</div>').join('')+'</section>';
    if(model.platformAdmin&&admin)html+=formStart('metaAppForm','Platform admin · Meta app configuration','Configure the platform’s Meta developer app once. Business owners then authorize their own Pages and Instagram accounts.')+'<div class="pair">'+field('appId','Meta App ID',admin.appId,'text','required maxlength="40"')+field('version','Graph API version',admin.version,'text','required maxlength="10"')+'</div>'+field('appSecret','App secret','','password',(admin.secretSet?'':'required ')+'maxlength="500" autocomplete="off"')+'<p class="small">'+(admin.secretSet?'A secret is saved. Leave this field empty to keep it.':'Enter the app secret from your Meta app settings.')+' Changing the app credentials requires clients to reconnect their social accounts.</p>'+formEnd('Save Meta app')+'<section class="card"><h2>Meta developer setup</h2><p class="small">Add the OAuth redirect below to Facebook Login. Configure the webhook for Page and Instagram messaging, subscribe to messages and messaging_postbacks, and complete Meta’s review for accounts outside your app’s test roles.</p>'+field('redirectURL','OAuth redirect URL',admin.redirectURL,'url','readonly')+field('webhookURL','Webhook callback URL',admin.callbackURL,'url','readonly')+field('verifyToken','Webhook verification token',admin.verifyToken,'text','readonly')+'<p class="small"><a href="https://developers.facebook.com/apps/" target="_blank" rel="noopener noreferrer">Open Meta app dashboard</a></p></section>';
    $('connectionsData').innerHTML=html;bind();
  }
  function websiteCode(c){const views=data.websiteVisits.find(v=>v.connectionId===c.id)?.views||0,code='<iframe data-profitplus-site="'+c.id+'" src="'+c.formURL+'" title="Customer enquiry form" width="100%" height="760" loading="lazy"></iframe>\n<script src="'+c.trackerURL+'" data-profitplus-site="'+c.id+'" defer></script>';return '<details class="channel-install"><summary>Install on your website</summary><p class="small">Add this code to your contact page. The form sends customer enquiries directly to this workspace. '+(c.visitsEnabled?'The script also counts anonymous page visits.':'Anonymous visit counting is disabled.')+'</p><textarea readonly rows="5" aria-label="Website embed code">'+esc(code)+'</textarea><p class="small"><a href="'+esc(c.formURL)+'" target="_blank" rel="noopener noreferrer">Open customer enquiry form</a> · '+views+' visits in the last 30 UTC days</p></details>';}
  async function submit(form,operation){const button=form.querySelector('[type=submit]'),error=form.querySelector('.error');button.disabled=true;error.hidden=true;try{await operation(Object.fromEntries(new FormData(form)));inlineDirty=false;await refresh(false);renderShell();await load();showToast('Connection settings saved.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{if(button.isConnected)button.disabled=false;}}
  function bind(){if($('websiteConnection'))$('websiteConnection').onsubmit=e=>{e.preventDefault();submit(e.target,values=>api('/integrations/website',{method:'POST',body:{...values,visitsEnabled:e.target.elements.visitsEnabled.checked}}));};if($('twilioConnection'))$('twilioConnection').onsubmit=e=>{e.preventDefault();submit(e.target,values=>api('/integrations/twilio',{method:'POST',body:values}));};if($('metaAppForm'))$('metaAppForm').onsubmit=e=>{e.preventDefault();submit(e.target,values=>api('/admin/channel-settings',{method:'PUT',body:values}));};$('connectionsData').querySelectorAll('[data-connection-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const a=b.dataset.connectionAction,id=b.dataset.id;if(a==='meta'){const result=await api('/integrations/meta/start',{method:'POST',body:{provider:id}});location.assign(result.url);return;}if(a==='asset')await api('/integrations/meta/connect',{method:'POST',body:{assetId:id}});if(a==='disconnect'){if(!confirm('Disconnect this channel? Captured enquiries remain in your workspace.'))return;const result=await api('/integrations/'+id+'/disconnect',{method:'POST',body:{}});if(result.warning)showToast(result.warning);}if(a==='retry')await api('/integrations/events/'+id+'/retry',{method:'POST',body:{customerId:$('connectionsData').querySelector('[data-pending-customer="'+CSS.escape(id)+'"]').value}});inlineDirty=false;await refresh(false);renderShell();await load();}catch(error){showToast(error.message);}finally{if(b.isConnected)b.disabled=false;}});}
  async function load(){if(demo||currentView!=='integrations')return;const version=++generation,userId=model.user?.id;try{const results=await Promise.all([api('/integrations'),model.platformAdmin?api('/admin/channel-settings'):Promise.resolve(null)]);if(version!==generation||userId!==model.user?.id||currentView!=='integrations'||demo)return;[data,admin]=results;draw();}catch(error){if(version===generation&&$('connectionsData'))$('connectionsData').innerHTML='<div class="error">'+esc(error.message)+'</div>';}}
  return{render,mount:load,reload:load,clear(){data=null;admin=null;generation++;}};
})();
